namespace detail {

    template<std::size_t I, typename R, typename F>
    inline constexpr R with_integral_constant(F f)
    {
      return static_cast<F>(f)(std::integral_constant<std::size_t, I>{});
    }

    } // namespace detail

    template<std::size_t N, typename R = void, typename F>
    inline constexpr R
    with_n(int n, F &&f)
    {
      constexpr auto invoke_array =
        []<std::size_t...I>(std::index_sequence<I...>) {
        return std::array{ detail::with_integral_constant<I, R, F&&>... };
      }(std::make_index_sequence<N>{});

      return invoke_array.at(n)(std::forward<F>(f));
    }

    template<typename T> requires requires {
      { std::variant_size_v<T>+0 } -> std::same_as<std::size_t>;
    }
    void
    set_index(T &t, std::size_t n)
    {
      with_n<std::variant_size_v<T>>(n, [&t](auto i) {
        t.template emplace<i>();
      });
    }

Some notes on the above code. First, note that  ` invoke_array ` , because it
is an array, must have all its elements be of the same type. Hence, we really
do need  ` detail::with_integral_constant ` to be a function, rather than a
lambda expression, to ensure all elements of the array have the same type. We
could create an array of  ` std::function<R(F&&)> ` , but `
std::function::~function ` is not a ` constexpr ` destructor, so then `
invoke_array ` could not be ` constexpr ` , which might inhibit some compiler
optimizations. (Note in some cases, if you have non-generic lambdas with no
variable capture, they can be  converted  to ordinary function pointers by
prefixing the lambda with ` + ` , as in ` +[]{} ` .)

