Data JPA tests may also inject a [ ` TestEntityManager `
](https://github.com/spring-projects/spring-boot/tree/v3.2.4/spring-boot-
project/spring-boot-test-
autoconfigure/src/main/java/org/springframework/boot/test/autoconfigure/orm/jpa/TestEntityManager.java)
bean, which provides an alternative to the standard JPA ` EntityManager ` that
is specifically designed for tests.

__ |  ` TestEntityManager ` can also be auto-configured to any of your Spring-based test class by adding ` @AutoConfigureTestEntityManager ` . When doing so, make sure that your test is running in a transaction, for instance by adding ` @Transactional ` on your test class or method.   
---|---  

A ` JdbcTemplate ` is also available if you need that. The following example
shows the ` @DataJpaTest ` annotation in use:

Java



    import org.junit.jupiter.api.Test;

    import org.springframework.beans.factory.annotation.Autowired;
    import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
    import org.springframework.boot.test.autoconfigure.orm.jpa.TestEntityManager;

    import static org.assertj.core.api.Assertions.assertThat;

    @DataJpaTest
    class MyRepositoryTests {

        @Autowired
        private TestEntityManager entityManager;

        @Autowired
        private UserRepository repository;

        @Test
        void testExample() {
            this.entityManager.persist(new User("sboot", "1234"));
            User user = this.repository.findByUsername("sboot");
            assertThat(user.getUsername()).isEqualTo("sboot");
            assertThat(user.getEmployeeNumber()).isEqualTo("1234");
        }

    }


Kotlin



    import org.assertj.core.api.Assertions.assertThat
    import org.junit.jupiter.api.Test
    import org.springframework.beans.factory.annotation.Autowired
    import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest
    import org.springframework.boot.test.autoconfigure.orm.jpa.TestEntityManager

    @DataJpaTest
    class MyRepositoryTests(@Autowired val entityManager: TestEntityManager, @Autowired val repository: UserRepository) {

        @Test
        fun testExample() {
            entityManager.persist(User("sboot", "1234"))
            val user = repository.findByUsername("sboot")
            assertThat(user?.username).isEqualTo("sboot")
            assertThat(user?.employeeNumber).isEqualTo("1234")
        }

    }


